-- PT116-S2-Q25. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT116-S2-Q25$batch03$ AND q.stimulus=$batch03$Burying beetles do whatever they can to minimize the size of their competitors’ broods without adversely affecting their own. This is why they routinely destroy each other’s eggs when two or more beetles inhabit the same breeding location. Yet, after the eggs hatch, the adults treat all of the larvae equally, sharing in the care of the entire population.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain burying beetles' apparently contradictory behavior?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT116-S2-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT116-S2-Q25$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S2-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT116-S2-Q25$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Burying beetles try to shrink competitors' broods without hurting their own, so they destroy each other's eggs.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$After hatching, adults care for all the larvae equally, competitors' included?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The behavior splits at hatching: rivals' *eggs* get destroyed, rivals' *larvae* get cared for. So look for a difference between eggs and larvae. Destroying eggs fits the goal. Caring for rivals' larvae does not, unless the beetles cannot tell whose larvae are whose. If they cannot, harming any larva risks harming their own, and their own goal is to protect their own brood.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a reason beetles cannot target competitors' larvae.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT116-S2-Q25$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Hatching order and brood size do not explain why adults care for every larva.$batch03$), ($batch03$B$batch03$, $batch03$Cooperation helps the most larvae survive, but the beetles are trying to *shrink* rivals' broods. This explains why caring for everyone produces many survivors, not why beetles who want fewer rival larvae would do it.$batch03$), ($batch03$C$batch03$, $batch03$If beetles cannot tell their own larvae from others', they cannot harm rivals' larvae without risking their own. Equal care follows from the same goal that drives egg destruction. (Eggs, presumably, they can identify by where they laid them.)$batch03$), ($batch03$D$batch03$, $batch03$Cooperating to defend the site explains joint defense. It does not explain why beetles that destroy rivals' eggs leave rivals' larvae alone and even feed them.$batch03$), ($batch03$E$batch03$, $batch03$If space for larvae is limited, a beetle has even more reason to remove rivals' larvae, not care for them.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT116-S2-Q25$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
